// ════════════════════════════════════════════════════════════════
// VITRINE — Node unico: recebe webhook Nuvemshop com secret, busca order
// VERSAO 3 — corrigido acesso ao body do webhook
// ════════════════════════════════════════════════════════════════

// 1. Recebe webhook da Nuvemshop
const webhook = $input.first().json;

// 1.1 VERIFICA SECRET
const EXPECTED_SECRET = 'Om2PvrFSAvZ7t43FtLroAMnL057cuxVWCi-o5ZXuGcw';
const receivedSecret = webhook.query?.secret || '';
if (receivedSecret !== EXPECTED_SECRET) {
  console.log('Unauthorized: secret invalido');
  return [{ json: { error: 'unauthorized', reason: 'invalid secret' } }];
}

// 2. Extrai dados do body (nao direto do webhook)
const body = webhook.body || webhook;
const storeId = body.store_id;
const eventName = body.event;
const orderId = body.id;

console.log('Webhook recebido:', { storeId, eventName, orderId });

// So processa order/paid (pode adicionar order/cancelled depois)
if (eventName !== 'order/paid') {
  return [{ json: { skipped: true, reason: `Evento ${eventName} ignorado` } }];
}

// 3. Credenciais Nuvemshop
const NUVEMSHOP_STORE_ID = '1307908';
const NUVEMSHOP_ACCESS_TOKEN = '71f66327cdc038e155513e38ac2b0163f876810d';
const NUVEMSHOP_USER_AGENT = 'Megazord-MVP (contato@jardimdofazer.com.br)';

// 4. Busca detalhes do pedido via GET /orders/{id}
let order;
try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.nuvemshop.com.br/2025-03/${NUVEMSHOP_STORE_ID}/orders/${orderId}`,
    headers: {
      'Authorization': `Bearer ${NUVEMSHOP_ACCESS_TOKEN}`,
      'User-Agent': NUVEMSHOP_USER_AGENT,
      'Content-Type': 'application/json',
    },
    timeout: 15000,
  });
  order = response;
} catch (e) {
  console.log('Erro ao buscar order:', e.message);
  return [{ json: { error: 'Nuvemshop API failed', message: e.message, orderId } }];
}

// 5. Extrai dados do pedido
const buyer = order.customer || {};
const products = order.products || [];
const firstProduct = products[0] || {};

const clickId = order.extra?.click_id
  || (order.attributes || []).find(a => a.name === 'click_id')?.value
  || null;

// 6. Monta objeto da venda
const venda = {
  data: order.paid_at || order.created_at || new Date().toISOString(),
  transaction_id: String(order.id || ''),
  product_id: String(firstProduct.product_id || ''),
  product_name: firstProduct.name || (products.length > 1 ? `${products.length} produtos` : ''),
  value_brl: parseFloat(order.total || 0),
  buyer_name: buyer.name || '',
  buyer_email: order.contact_email || buyer.email || '',
  click_id: clickId || '',
  event: eventName,
};

// 7. UTMs default (direct)
let utms = {
  utm_source: 'direct',
  utm_medium: '',
  utm_campaign: '',
  utm_content: '',
  utm_term: '',
};

// 8. Se tem click_id, busca UTMs no Supabase
if (clickId && clickId.length > 0) {
  try {
    const supaResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://fbeofenkrvmqdlmgjfna.supabase.co/rest/v1/clicks?click_id=eq.${clickId}&select=utm_source,utm_medium,utm_campaign,utm_content,utm_term`,
      headers: {
        apikey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZiZW9mZW5rcnZtcWRsbWdqZm5hIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTA2Mzk3NzIsImV4cCI6MjEwNjIxNTc3Mn0.fHBBbNAM4BUpBoS2-mvxmlgFFe9XCXk7w0DmnfJT2jg',
        Authorization: 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZiZW9mZW5rcnZtcWRsbWdqZm5hIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTA2Mzk3NzIsImV4cCI6MjEwNjIxNTc3Mn0.fHBBbNAM4BUpBoS2-mvxmlgFFe9XCXk7w0DmnfJT2jg',
      },
      timeout: 10000,
    });
    if (Array.isArray(supaResponse) && supaResponse.length > 0) {
      utms = {
        utm_source: supaResponse[0].utm_source || 'direct',
        utm_medium: supaResponse[0].utm_medium || '',
        utm_campaign: supaResponse[0].utm_campaign || '',
        utm_content: supaResponse[0].utm_content || '',
        utm_term: supaResponse[0].utm_term || '',
      };
    }
  } catch (e) {
    console.log('Supabase lookup failed:', e.message);
  }
}

// 9. Devolve pro Google Sheets
return [{
  json: {
    ...venda,
    ...utms,
  }
}];
